public String minWindow(String s, String t) {
    int[] need = new int[128];
    for (char c : t.toCharArray()) {
        need[c]++;
    }
    // counts：还差几个必需字符没被满足；0 表示当前窗口已覆盖 t
    int counts = t.length();
    String ans = "";
    int min = Integer.MAX_VALUE;
    int start = 0;
    int i = 0;
    while (i < s.length()) {
        char c = s.charAt(i);
        // 判断只决定计数器：只有「还没被满足的必需字符」才让 counts 减 1
        if (need[c] > 0) {
            counts--;
        }
        // 减法无条件执行：多余字符与不在 t 里的字符被减成负数，收缩时才有「可删」的凭证
        need[c]--;
        if (counts == 0) {
            // 收缩只删多余（need < 0），恰好满足的字符留着
            while (need[s.charAt(start)] < 0) {
                need[s.charAt(start)]++;
                start++;
            }
            if (i - start + 1 < min) {
                min = i - start + 1;
                ans = s.substring(start, i + 1);
            }
            // 记录后把左端必需字符还回去，窗口整体前移继续找
            need[s.charAt(start)]++;
            counts++;
            start++;
        }
        i++;
    }
    return ans;
}

